const raw = $input.first().json;
const body = raw.body ?? raw;

const taskTitle = body.taskTitle || 'Adsız Proje';
const taskDescription = body.taskDescription || '';
const userId = body.userId || null;
const supabaseToken = body.supabaseToken || null;
const googleAccessToken = body.googleAccessToken || null;

const profile = body.userProfile || {};
const focusPeriod = profile.focusPeriod ?? 25;
const energyPeak = profile.energyPeak ?? 'morning';
const workHours = profile.workHours ?? { start: '09:00', end: '18:00' };
const mainObstacle = profile.mainObstacle ?? 'paralysis';
const breakStyle = profile.breakStyle ?? 'long-break';
// 2026-08-28: on yuz artik profilin TAMAMINI gonderiyor (planningProfile,
// profile-logic.js). Asagidakiler daha once toplanip hicbir yere ulasmiyordu.
const medication = profile.medication ?? false;
const hyperfocusLimit = profile.hyperfocusLimit ?? 'none';
const todayMood = profile.todayMood ?? '';
const focusTrigger = profile.focusTrigger ?? 'silence';
const social = profile.social ?? 'solo';
const motivationNote = profile.motivationNote ?? '';
const rsdLevel = Number(profile.rsdLevel) || 2;
const soundSensitivity = Number(profile.soundSensitivity) || 2;
const envPref = profile.envPref ?? 'minimal';
const regulationMethod = profile.regulationMethod ?? 'breathing';
const stimPref = profile.stimPref ?? 'fidget';
const superpowers = Array.isArray(profile.superpowers) ? profile.superpowers : [];

const deadlineRaw = body.deadline || body.targetDate;
if (!deadlineRaw) {
  throw new Error("Webhook payload'inda deadline veya targetDate olmali");
}

const now = new Date();
let deadline = new Date(deadlineRaw);
if (!body.deadline && body.targetDate) {
  deadline.setHours(23, 59, 0, 0);
}

const msPerDay = 24 * 60 * 60 * 1000;
const availableDays = Math.max(1, Math.ceil((deadline.getTime() - now.getTime()) / msPerDay));

// Gunluk kapasite: calisma saatlerine kac odak seansi sigar
function toMin(hhmm) { const p = String(hhmm).split(':').map(Number); return (p[0] || 0) * 60 + (p[1] || 0); }
const breakMap = { pomodoro: 5, 'long-break': 15, micro: 2, free: 0 };
const breakMinutes = breakMap[breakStyle] != null ? breakMap[breakStyle] : 15;
// Gece yarisini asan calisma penceresi (ör. 20:00 -> 06:00): bitis, baslangictan kucukse
// pencere ertesi gune tasiyor demektir, suresi (1440 - baslangic + bitis) olur.
const workStartMinN = toMin(workHours.start);
const workEndMinRawN = toMin(workHours.end);
const sessionDurationN = workEndMinRawN <= workStartMinN ? (1440 - workStartMinN + workEndMinRawN) : (workEndMinRawN - workStartMinN);
const slotsPerDay = Math.max(1, Math.floor(sessionDurationN / (focusPeriod + breakMinutes)));
let perDayCap = Math.min(slotsPerDay, 3); // DEHB: gunde en fazla ~3 odak seansi

// Bugunku mod gunluk kapasiteyi degistirir. Beyin sisi/enerji dususunde ayni
// yuku planlamak plani bastan cope atiyor; hiper/odakli gunde bir seans fazla.
if (todayMood === 'foggy' || todayMood === 'crash') perDayCap = Math.max(1, perDayCap - 1);
else if (todayMood === 'hyper' || todayMood === 'focused') perDayCap = Math.min(slotsPerDay, perDayCap + 1);

// Hiperfokus uyarisi kesintisiz seans suresini sinirlar: 60/90/120 dk secildiyse
// tek seans bunu asamaz. 'none' ise sinir yok.
const hyperfocusCap = hyperfocusLimit === 'none' ? null : Number(hyperfocusLimit);
const effectiveFocus = hyperfocusCap ? Math.min(focusPeriod, hyperfocusCap) : focusPeriod;

// RSD yuksekse (4-5) is daha kucuk parcalara bolunur: buyuk bir gorevin yarim
// kalmasi elestiri/basarisizlik hissini tetikliyor.
const rsdCarpani = rsdLevel >= 4 ? 1.5 : 1;

// Gorev sayisi araligi — AI karmasikliga gore bu aralikta secer
const minTasks = Math.max(3, Math.ceil(availableDays / 2 * rsdCarpani));
const maxTasks = Math.max(minTasks + 1, Math.ceil(availableDays * perDayCap * rsdCarpani));

return [{
  json: {
    taskTitle,
    taskDescription,
    userId,
    supabaseToken,
    googleAccessToken,
    now: now.toISOString(),
    deadline: deadline.toISOString(),
    availableDays,
    minTasks,
    maxTasks,
    profile: { focusPeriod, energyPeak, workHours, mainObstacle, breakStyle, breakMinutes,
               effectiveFocus, medication, hyperfocusLimit, todayMood, focusTrigger,
               social, motivationNote, rsdLevel, soundSensitivity, envPref,
               regulationMethod, stimPref, superpowers }
  }
}];

