// ── FocusAid — Görev Dağıtımı (rapor algoritması, mutlak-dakika zaman çizgisi) ──
// AI Agent sadece görev + cognitive_load üretir; planlamayı burada yaparız.
const merged = $('Merge').first().json;
const aiRaw = $json.output || '{"tasks":[]}';

let parsed;
try { parsed = JSON.parse(aiRaw); }
catch (e) { throw new Error('AI Agent gecerli JSON dondurmedi: ' + String(aiRaw).slice(0, 300)); }
const rawTasks = Array.isArray(parsed) ? parsed : (parsed.tasks || []);
if (rawTasks.length === 0) throw new Error('AI Agent hic gorev uretmedi');

const profile = merged.profile || {};
const workHours = profile.workHours || {};
const focusPeriod = profile.focusPeriod || 25;
const existingEvents = merged.existingEvents || [];

// Mola süresi (dk): profil breakStyle'a göre, yoksa 15 dk (rapor: en az 15 dk ara)
const breakMap = { pomodoro: 5, 'long-break': 15, micro: 2, free: 0 };
const breakMinutes = (profile.breakMinutes != null) ? Number(profile.breakMinutes)
  : (breakMap[profile.breakStyle] != null ? breakMap[profile.breakStyle] : 15);
const step = focusPeriod + breakMinutes;

function pad(n) { return String(n).padStart(2, '0'); }
function toMin(hhmm) { const p = String(hhmm).split(':').map(Number); return (p[0] || 0) * 60 + (p[1] || 0); }
const workStartMin = toMin(workHours.start || '09:00');
const workEndMinRaw = toMin(workHours.end || '18:00');
// Gece yarisini asan pencere (ör. 20:00 -> 06:00): bitis <= baslangic ise pencere ertesi gune tasar.
const overnight = workEndMinRaw <= workStartMin;
const sessionDuration = overnight ? (1440 - workStartMin + workEndMinRaw) : (workEndMinRaw - workStartMin);

// Istanbul (UTC+3) duvar saati — sunucu timezone'undan bağımsız
const IST = 3 * 3600 * 1000;
function wall(iso) { return new Date(new Date(iso).getTime() + IST); }

const nowW = wall(merged.now || new Date().toISOString());
const deadW = wall(merged.deadline || merged.now);

// epoch0: bugünün (yerel) gece yarısı — tüm zaman çizelgesi buradan itibaren TEK bir mutlak
// dakika sayı doğrusu olarak tutulur. Bu sayede gece-aşan pencereler ve gün sınırları ayrı
// özel-durum kodu gerektirmeden doğal biçimde çözülür.
const epoch0 = Date.UTC(nowW.getUTCFullYear(), nowW.getUTCMonth(), nowW.getUTCDate());
function absMinOf(w) { return Math.round((w.getTime() - epoch0) / 60000); }
function dateFromAbsMin(m) { return new Date(epoch0 + m * 60000); }
function dayKeyFromAbsMin(m) { const d = dateFromAbsMin(m); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); }
function isoFromAbsMin(m) { const d = dateFromAbsMin(m); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + 'T' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':00+03:00'; }

const nowAbsMin = absMinOf(nowW);
const deadlineAbsMin = absMinOf(deadW);

// 1) scheduledSlots — mevcut takvim etkinliklerinden dolu aralıklar (mutlak dakika ekseninde)
const occ = [];
function reserve(a, b) { occ.push({ a, b }); }
function isFree(a, b) { return !occ.some(o => a < o.b && b > o.a); }
for (const ev of existingEvents) {
  const s = ev.start && (ev.start.dateTime || ev.start.date);
  const e = ev.end && (ev.end.dateTime || ev.end.date);
  if (!s || !e) continue;
  reserve(absMinOf(wall(s)), absMinOf(wall(e)));
}

// 2) Her takvim gününde bir çalışma seansı: [gün_başı + workStart, +sessionDuration).
//    Gece-aşan pencerede bu araligin sonu dogal olarak ertesi gune tasar (mutlak dakika sayesinde).
const LEAD_MIN = 15; // gorev en erken 15 dk sonra baslasin (bugunku ilk seans icin)
const sessions = [];
for (let dayOffset = 0; dayOffset <= 60; dayOffset++) {
  const sessionStartAbs = dayOffset * 1440 + workStartMin;
  if (sessionStartAbs > deadlineAbsMin) break;
  const sessionEndAbs = sessionStartAbs + sessionDuration;
  const effectiveEnd = Math.min(sessionEndAbs, deadlineAbsMin);
  const effectiveStart = dayOffset === 0 ? Math.max(sessionStartAbs, nowAbsMin + LEAD_MIN) : sessionStartAbs;
  if (effectiveStart + focusPeriod > effectiveEnd) continue; // bu seansta hic yer yok
  sessions.push({ key: dayKeyFromAbsMin(sessionStartAbs), start: effectiveStart, end: effectiveEnd });
}
if (sessions.length === 0) {
  const sessionStartAbs = 1440 + workStartMin; // deadline cok yakinsa/gecmisse: en azindan yarina bir seans ac
  sessions.push({ key: dayKeyFromAbsMin(sessionStartAbs), start: sessionStartAbs, end: sessionStartAbs + sessionDuration });
}

// 3) maxPerDay + proportional dağıtım
const T = rawTasks.length;
const A = sessions.length;
const maxPerDay = Math.ceil(T / A);
const count = {};
function findSlot(session) {
  if ((count[session.key] || 0) >= maxPerDay) return null;
  for (let m = session.start; m + focusPeriod <= session.end; m += step) {
    if (isFree(m, m + focusPeriod)) return m;
  }
  return null;
}

const results = [];
for (let i = 0; i < T; i++) {
  const t = rawTasks[i] || {};
  const targetIdx = A > 1 ? Math.round(i * (A - 1) / (T - 1)) : 0;

  let session = null, startAbs = null;
  let s = findSlot(sessions[targetIdx]);
  if (s !== null) { session = sessions[targetIdx]; startAbs = s; }
  for (let j = targetIdx + 1; session === null && j < A; j++) { const x = findSlot(sessions[j]); if (x !== null) { session = sessions[j]; startAbs = x; } }
  for (let j = targetIdx - 1; session === null && j >= 0; j--) { const x = findSlot(sessions[j]); if (x !== null) { session = sessions[j]; startAbs = x; } }
  if (session === null) { session = sessions[A - 1]; startAbs = session.start; } // taşma: son seansa zorla

  reserve(startAbs, startAbs + focusPeriod);
  count[session.key] = (count[session.key] || 0) + 1;

  results.push({
    json: {
      title: t.title || t.name || ('Gorev ' + (i + 1)),
      summary: t.summary || '',
      cognitiveLoad: t.cognitiveLoad || t.cognitive_load || 'medium',
      day: session.key,
      start: isoFromAbsMin(startAbs),
      end: isoFromAbsMin(startAbs + focusPeriod),
      userId: merged.userId,
      supabaseToken: merged.supabaseToken,
      googleAccessToken: merged.googleAccessToken,
      projectTitle: merged.taskTitle
    }
  });
}

return results;

// Her takvim etkinligi icin bir Supabase satiri uret.
// ONCEKI HATA: runOnceForAllItems modunda tek nesne donduruluyordu; N gorev
// parcalansa da Supabase'e yalnizca 1 kayit gidiyordu.
const events = $input.all();
const tasks  = $('Code in JavaScript').all();

return events.map((item, i) => {
  const task  = (tasks[i] || tasks[0]).json;
  const event = item.json;
  return {
    json: {
      user_id:           task.userId,
      project_title:     task.projectTitle,
      name:              task.title,
      summary:           task.summary,
      cognitive_load:    task.cognitiveLoad,
      day:               task.day,
      start_time:        task.start,
      end_time:          task.end,
      calendar_event_id: event.id,
      completed:         false
    }
  };
});
